def collapse_whitespace(s):
    """Collapse runs of ASCII whitespace into single space and strip ends."""
    result = []
    in_space = True
    for ch in s:
        # ASCII whitespace: space, tab, LF, CR, vertical tab, form feed
        if ch in (' ', '\t', '\n', '\r', '\x0b', '\x0c'):
            if not in_space:
                result.append(' ')
                in_space = True
        else:
            result.append(ch)
            in_space = False
    # Strip leading and trailing spaces
    # Convert to string and use strip for the ASCII whitespace only
    collapsed = ''.join(result)
    # Manual strip of leading/trailing ASCII space
    start = 0
    while start < len(collapsed) and collapsed[start] == ' ':
        start += 1
    end = len(collapsed)
    while end > start and collapsed[end - 1] == ' ':
        end -= 1
    return collapsed[start:end]
